SELECT p.sku, p.path, p.brand, p.series, p.model, json_extract(p.properties,'$.screw_type') AS screw_type, json_extract(p.properties,'$.diameter') AS diameter FROM products p WHERE p.brand='Heco' AND p.series LIKE '%Heco Zinc Plated TopFix GTU-YPJ%' AND p.model='Wood and Drywall Screw' AND json_extract(p.properties,'$.screw_type')='wood screw' AND json_extract(p.properties,'$.diameter')='6 mm' LIMIT 10;
SELECT store_id, name, city FROM stores WHERE city='Vienna' ORDER BY store_id;
SELECT i.store_id, i.available_today FROM inventory i JOIN stores s ON s.store_id=i.store_id WHERE s.city='Vienna' AND i.sku IN (SELECT p2.sku FROM products p2 WHERE p2.brand='Heco' AND p2.series LIKE '%Heco Zinc Plated TopFix GTU-YPJ%' AND p2.model='Wood and Drywall Screw' AND json_extract(p2.properties,'$.screw_type')='wood screw' AND json_extract(p2.properties,'$.diameter')='6 mm') ORDER BY i.store_id;

